local KTool = CS.Engine.Lib.KTool

--- from: Assets/BundleResources/Prefabs/Action/ActionDarkDreamMainDialog.prefab > name: RoleUp
---@class CommonRoleUpNode
---@field Env                           	CommonRoleUpNode                        
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field Role1                         	UnityEngine.RectTransform               
---@field RoleNode                      	UnityEngine.RectTransform               
local CommonRoleUpNode = Class('CommonRoleUpNode')
function CommonRoleUpNode:__init()
    self.node = nil
end

function CommonRoleUpNode:__delete()
    for i, v in pairs(self.node) do
        if i > 1 then
            CfUtils.SafeDelete(v.gameObject)
        end
    end
end

function CommonRoleUpNode:Awake()
    self.node = {}
    table.insert(self.node,self.Role1.gameObject)
end

function CommonRoleUpNode:RefreshShow(data,callBack,excludeDialogs)
    KTool.SetActive(self.controller.gameObject,table.count(data) > 0)
    if table.count(data) <= 0 then
        return
    end

    for i = 1, self.RoleNode.transform.childCount do
        local child = self.RoleNode.transform:GetChild(i - 1)
        CfUtils.SetActive(child.gameObject,false)
    end

    for i, v in pairs(data) do
        local node = self.node[i]
        if not node then
            node = CS.UnityEngine.Object.Instantiate(self.Role1.gameObject)
            KTool.SetParent(node.gameObject,self.RoleNode.gameObject,false)
            node.name = "Role"..i
            table.insert(self.node,node.gameObject)
        end

        if not isNull(node) then
            local env = CfUtils.GetLuaScr(node,"Game.Behaviours.CommonRoleUpNodeCell")
            if not isNull(env) then
                env:RefreshCellShow(v,callBack,excludeDialogs)
            end
            CfUtils.SetActive(node.gameObject,true)
        end
    end
end

function CommonRoleUpNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return CommonRoleUpNode